	if err != nil {
		t.Fatal(err)
	}
	sim.Mode = "rtn"

	g, err := NewHeadGPUBank(dev, nEmbd, w, 4, BankQ4K, sim)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()

	x := make([]float32, nEmbd)
	for i := range x {
		x[i] = float32(rng.NormFloat64())
	}
	if err := g.Upload(x, 1); err != nil {
		t.Fatal(err)
	}
	if err := g.Run(); err != nil {
		t.Fatal(err)
	}
	gemm := append([]float32(nil), g.Logits()[:vocab]...)

